import math
R = 6371.0088
def cell_area_km2(lat_south: float, d: float = 0.1) -> float:
    """A = R^2 * dlon * (sin(phi2) - sin(phi1))."""
    return R * R * math.radians(d) * (math.sin(math.radians(lat_south + d)) - math.sin(math.radians(lat_south)))

