def pearson_dispersion(y, mu, p):
    """phi = sum((y-mu)^2/mu)/(n-p); NB when phi > 1.5."""
    y, mu = np.asarray(y, float), np.asarray(mu, float)
    return float(np.sum((y - mu) ** 2 / mu) / (len(y) - p))

def ratio_ci_delta(v, m, z=1.96):
    if v <= 0 or m <= 0:
        return None
    k = v / m
    se = (1 / v + 1 / m) ** 0.5
    return k * np.exp(-z * se), k * np.exp(z * se)

def shrink(k_loc, n, k_glob, n0=4):
    if k_loc is None:
        return k_glob
    return (n * k_loc + n0 * k_glob) / (n + n0)

