def boot_k(v, m, B=2000, alpha=0.05, seed=26):
    rng = np.random.default_rng(seed)
    idx = np.arange(len(v)); ks = []
    for _ in range(B):
        s = rng.choice(idx, len(idx), replace=True)
        if m[s].sum() > 0:
            ks.append(v[s].sum() / m[s].sum())
    return np.quantile(ks, [alpha / 2, 1 - alpha / 2])

def robust_z(history: dict, target_year: int, floor=0.15, min_ref=8):
    ref = [np.log(v + 0.5) for y, v in history.items() if y != target_year and v is not None]
    if not ref:
        return None, "insufficient"
    med = np.median(ref)
    spread = max(1.4826 * np.median(np.abs(np.array(ref) - med)), floor)
    z = (np.log(history[target_year] + 0.5) - med) / spread
    return z, ("ok" if len(ref) >= min_ref else "indicative")

def season_dates(weekly, start=0.10, end=0.90):
    w = np.asarray(weekly, float)
    if np.isnan(w).any() or w.sum() == 0:
        return None
    c = np.cumsum(w) / w.sum()
    return int(np.argmax(c >= start)), int(np.argmax(w)), int(np.argmax(c >= end))

def pettitt(x):
    n = len(x)
    U = [sum(np.sign(x[j] - x[i]) for i in range(t + 1) for j in range(t + 1, n)) for t in range(n - 1)]
    K = max(abs(u) for u in U)
    return int(np.argmax(np.abs(U))), K, min(1, 2 * np.exp(-6 * K**2 / (n**3 + n**2)))

