def night_fraction(n_day, n_night, e_day=1, e_night=1):
    if n_day + n_night < 10:
        return None
    rd, rn = n_day / e_day, n_night / e_night
    return rn / (rd + rn)

from scipy.stats import norm
def seen_union(windows, mu, sigma):
    merged = []
    for a, b in sorted(windows):
        if merged and a <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    return sum(norm.cdf(b, mu, sigma) - norm.cdf(a, mu, sigma) for a, b in merged)

def blindspot_ratio(ba_km2, cell_days, ref_ratios):
    if ba_km2 is None:
        return None, "pending"
    if not cell_days:
        return None, "unavailable"
    if len(ref_ratios) < 3:
        return None, "insufficient"
    return (ba_km2 / cell_days) / np.median(ref_ratios), "ok"
